create extension if not exists "pgcrypto"; create table if not exists public.profiles ( id uuid primary key references auth.users(id) on delete cascade, email text, full_name text, plan text not null default 'free' check (plan in ('free','pro','business')), subscription_status text default 'inactive', stripe_customer_id text, stripe_subscription_id text, created_at timestamptz not null default now(), updated_at timestamptz not null default now() ); create table if not exists public.documents ( id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, title text not null, type text not null check (type in ('cv','invoice')), data jsonb not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now() ); alter table public.profiles enable row level security; alter table public.documents enable row level security; create policy "profiles own row" on public.profiles for select using (auth.uid() = id); create policy "profiles own update" on public.profiles for update using (auth.uid() = id); create policy "documents own select" on public.documents for select using (auth.uid() = user_id); create policy "documents own insert" on public.documents for insert with check (auth.uid() = user_id); create policy "documents own update" on public.documents for update using (auth.uid() = user_id); create policy "documents own delete" on public.documents for delete using (auth.uid() = user_id); create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles(id,email,full_name) values(new.id,new.email,coalesce(new.raw_user_meta_data->>'full_name','')); return new; end; $$; drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user()
